-- 33 Hillside Hamlet: picks the cell under the mouse in an isometric
-- tilemap and plants or clears a tree there; turns each villager to face the
-- way it walks. The drawing, the sorting of houses, trees and villagers, and
-- the lanes' edges are the engine's. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/33-hillside-hamlet.scene"
local N = 16
local VILLAGERS = 6
local TREE, TREE2 = 39, 40
local post_on = nav.post_all_on(SCENE)
local captions = true
local map, cursor, status
local walkers = {}

function init(entity)
    map = Entity.find_by_name("Map")
    cursor = Entity.find_by_name("Cursor")
    status = Entity.find_by_name("Status")
    for i = 1, VILLAGERS do
        local v = Entity.find_by_name("Villager" .. i)
        if v then
            local x = Transform.get_position(v)
            walkers[#walkers + 1] = { e = v, x = x, facing = 1 }
        end
    end
end

local GROUND = { [0] = "grass", [1] = "lane", [2] = "pond" }

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if map == nil then return end

    -- Face the way each villager walks (the art faces right).
    for _, w in ipairs(walkers) do
        local x = Transform.get_position(w.e)
        local dx = x - w.x
        w.x = x
        local facing = w.facing
        if dx > 0.01 then facing = 1 elseif dx < -0.01 then facing = -1 end
        if facing ~= w.facing then
            w.facing = facing
            Transform.set_scale(w.e, facing, 1)
        end
    end

    local wx, wy = Input.get_mouse_world_position()
    local c, r = Tilemap.world_to_tile(map, wx, wy)
    local inside = c ~= nil and c >= 0 and r >= 0 and c < N and r < N
    if cursor then
        if inside then
            local cx, cy = Tilemap.tile_to_world(map, c, r)
            Transform.set_position(cursor, cx, cy)
            Sprite.set_color(cursor, 1.0, 0.92, 0.55, 0.9)
        else
            Sprite.set_color(cursor, 1.0, 0.92, 0.55, 0.0)
        end
    end
    if not inside then
        if status then UI.set_text(status, "") end
        return
    end
    local ground = GROUND[Tilemap.get_tile(map, "terrain", c, r)] or "grass"
    local thing = Tilemap.get_tile(map, "objects", c, r)
    if status then
        local what = ground
        if thing > 0 then what = what .. ", something on it" end
        UI.set_text(status, "cell " .. c .. ", " .. r .. "   " .. what)
    end
    if Input.is_mouse_left_just_pressed() and ground == "grass" then
        if thing == 0 then
            Tilemap.set_tile(map, "objects", c, r, ((c + r) % 2 == 0) and TREE or TREE2)
        elseif thing == TREE or thing == TREE2 then
            Tilemap.set_tile(map, "objects", c, r, 0)
        end
    end
end
